55	int bt_app_hci_event_handler(uint16_t event_id, uint8_t *msg)
56	{
57	    switch (event_id)
58	    {
59	    case DM_EN_ACL_OPENED_IND:
60	    {
61	        BTS2S_DM_EN_ACL_OPENED_IND *ind = (BTS2S_DM_EN_ACL_OPENED_IND *)msg;
62	
63	        LOG_I("[bt_app]link connected COD:%d Incoming:%d res %d\r\n", ind->dev_cls, ind->incoming, ind->st);
64	        LOG_I("[bt_app]bd addr %x-%x-%x\r\n", ind->bd.nap, ind->bd.uap, ind->bd.lap);
65	
66	        // Enable first
67	        if (ind->st != HCI_SUCC)
68	        {
69	            LOG_I("[bt_app]acl connect fail!!!!\n");
70	        }
71	        else
72	        {
73	            memcpy(&g_bt_app_env.bd_addr, &ind->bd, sizeof(BTS2S_BD_ADDR));
74	            g_bt_app_env.bt_connected = TRUE;
75	            g_bt_app_env.connected_profile = 0;
76	        }
77	        break;
78	    }
79	    case DM_ACL_DISC_IND:
80	    {
81	        BTS2S_DM_ACL_DISC_IND *ind = (BTS2S_DM_ACL_DISC_IND *)msg;
82	        LOG_I("[bt_app]link dis-connected %x %d\r\n", ind->hdl, ind->reason);
83	
84	        g_bt_app_env.bt_connected = FALSE;
85	        g_bt_app_env.connected_profile = 0;
86	
87	        g_bt_app_env.bd_addr.lap = CFG_BD_LAP;
88	        g_bt_app_env.bd_addr.nap = CFG_BD_NAP;
89	        g_bt_app_env.bd_addr.uap = CFG_BD_UAP;
90	        break;
91	    }
92	    }
93	
94	    return 0;
95	}
