157	#define DEFAULT_LOCAL_NAME "SIFLI_APP"
158	/* Enable advertise via advertising service. */
159	static void ble_app_advertising_start(void)
160	{
161	    sibles_advertising_para_t para = {0};
162	    uint8_t ret;
163	
164	    char local_name[31] = {0};
165	    uint8_t manu_additnal_data[] = {0x20, 0xC4, 0x00, 0x91};
166	    uint16_t manu_company_id = 0x01;
167	    bd_addr_t addr;
168	    ret = ble_get_public_address(&addr);
169	    if (ret == HL_ERR_NO_ERROR)
170	        rt_snprintf(local_name, 31, "SIFLI_APP-%x-%x-%x-%x-%x-%x", addr.addr[0], addr.addr[1], addr.addr[2], addr.addr[3], addr.addr[4], addr.addr[5]);
171	    else
172	        memcpy(local_name, DEFAULT_LOCAL_NAME, sizeof(DEFAULT_LOCAL_NAME));
173	
174	    ble_gap_dev_name_t *dev_name = malloc(sizeof(ble_gap_dev_name_t) + strlen(local_name));
175	    dev_name->len = strlen(local_name);
176	    memcpy(dev_name->name, local_name, dev_name->len);
177	    ble_gap_set_dev_name(dev_name);
178	    free(dev_name);
179	
180	    para.own_addr_type = GAPM_STATIC_ADDR;
181	    para.config.adv_mode = SIBLES_ADV_CONNECT_MODE;
182	    /* Keep advertising till disable it or connected. */
183	    para.config.mode_config.conn_config.duration = 0x0;
184	    para.config.mode_config.conn_config.interval = 0x30;
185	    para.config.max_tx_pwr = 0x7F;
186	    /* Advertising will re-start after disconnected. */
187	    para.config.is_auto_restart = 1;
188	    /* Scan rsp data is same as advertising data. */
189	    //para.config.is_rsp_data_duplicate = 1;
190	
191	    /* Prepare name filed. Due to name is too long to put adv data, put it to rsp data.*/
192	    para.rsp_data.completed_name = rt_malloc(rt_strlen(local_name) + sizeof(sibles_adv_type_name_t));
193	    para.rsp_data.completed_name->name_len = rt_strlen(local_name);
194	    rt_memcpy(para.rsp_data.completed_name->name, local_name, para.rsp_data.completed_name->name_len);
195	
196	    /* Prepare manufacturer filed .*/
197	    para.adv_data.manufacturer_data = rt_malloc(sizeof(sibles_adv_type_manufacturer_data_t) + sizeof(manu_additnal_data));
198	    para.adv_data.manufacturer_data->company_id = manu_company_id;
199	    para.adv_data.manufacturer_data->data_len = sizeof(manu_additnal_data);
200	    rt_memcpy(para.adv_data.manufacturer_data->additional_data, manu_additnal_data, sizeof(manu_additnal_data));
201	
202	    para.evt_handler = ble_app_advertising_event;
203	
204	    ret = sibles_advertising_init(g_app_advertising_context, &para);
205	    if (ret == SIBLES_ADV_NO_ERR)
206	    {
207	        sibles_advertising_start(g_app_advertising_context);
208	    }
209	
210	    rt_free(para.rsp_data.completed_name);
211	    rt_free(para.adv_data.manufacturer_data);
212	}
